package com.stellasora.viethoa.localadb;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.Build;import org.json.JSONObject;
/** Separate APK notice; metadata is verified by ChannelClient before use. */
final class LauncherUpdateNotice {
 private static final int ID=10403;private static final String CHANNEL="launcher_updates";
 private static SharedPreferences p(Context c){return c.getSharedPreferences("launcher_notice",Context.MODE_PRIVATE);}
 static synchronized void observe(Context c,String repo,JSONObject metadata,String changes,boolean background){synchronized(UpdateNotice.class){if(!UpdateNotice.currentChannel(c,repo))return;
  if(metadata==null)return;long code=metadata.optLong("version_code",0);String version=metadata.optString("version_name");if(code<=0||version.isEmpty())return;
  SharedPreferences s=p(c);if(!repo.equals(s.getString("repo","")))s.edit().clear().putString("repo",repo).apply();
  String summary=changes==null?"":changes.replaceAll("[\\r\\n]+"," ").replaceAll("[#*`]+","").trim();if(summary.length()>900)summary=summary.substring(0,900)+"…";if(summary.isEmpty())summary="Mở launcher để xem bản cập nhật ứng dụng.";else summary="Ghi chú bản phát hành chung: "+summary;
  s.edit().putLong("code",code).putString("version",version).putString("summary",summary).apply();if(background)notifyIfNeeded(c);}
 }
 private static void notifyIfNeeded(Context c){SharedPreferences s=p(c);if(!UpdateNotice.currentChannel(c,s.getString("repo","")))return;long code=s.getLong("code",0);if(code<=0||code==s.getLong("notified",0)||System.currentTimeMillis()<s.getLong("snooze_until",0))return;if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel(CHANNEL,"Cập nhật launcher",NotificationManager.IMPORTANCE_DEFAULT));if(!n.areNotificationsEnabled()||n.getNotificationChannel(CHANNEL).getImportance()==NotificationManager.IMPORTANCE_NONE)return;Intent i=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent open=PendingIntent.getActivity(c,ID,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String summary=s.getString("summary","");n.notify(ID,new Notification.Builder(c,CHANNEL).setSmallIcon(R.drawable.ic_notification).setContentTitle("Có launcher mới "+s.getString("version","")).setContentText(summary).setStyle(new Notification.BigTextStyle().bigText(summary)).setAutoCancel(true).setContentIntent(open).build());s.edit().putLong("notified",code).apply();}
 static synchronized void clearIfCurrent(Context c,String repo){synchronized(UpdateNotice.class){if(!UpdateNotice.currentChannel(c,repo))return;SharedPreferences s=p(c);if(repo.equals(s.getString("repo",""))){s.edit().remove("code").remove("notified").remove("dismissed").remove("version").remove("summary").apply();((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(ID);}}}
 static synchronized String[] pending(Context c){SharedPreferences s=p(c);try{JSONObject cfg=Store.config(c);if(!(cfg.optString("repo")+"/"+cfg.optString("branch")).equals(s.getString("repo","")))return null;}catch(Exception e){return null;}long code=s.getLong("code",0);try{if(code<=c.getPackageManager().getPackageInfo(Store.APP,0).getLongVersionCode()){s.edit().remove("code").remove("notified").remove("dismissed").apply();((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(ID);return null;}}catch(PackageManager.NameNotFoundException e){return null;}if(code<=0||code==s.getLong("dismissed",0)||System.currentTimeMillis()<s.getLong("snooze_until",0))return null;return new String[]{s.getString("version",""),s.getString("summary",""),Long.toString(code)};}
 static synchronized void dismiss(Context c,long code){p(c).edit().putLong("dismissed",code).apply();}
 static synchronized void snooze(Context c){p(c).edit().putLong("snooze_until",System.currentTimeMillis()+24L*60*60*1000).remove("notified").apply();}
}
